#include <chrono>
#include <type_traits>
#include <cassert>
#include <iostream>

int main() {
    using namespace std::chrono;
    time_point<steady_clock, seconds> start{seconds{10}};
    auto later = start + seconds{3};
    assert(later - start == seconds{3});
    ++later;
    --later;
    later += seconds{2};
    later -= seconds{1};
    assert(later > start);
    using Common =
        std::common_type_t<decltype(start), time_point<steady_clock, milliseconds>>;
    Common precise = start;
    assert(precise.time_since_epoch() == milliseconds{10000});
    std::cout << "Checks passed\n";
}
